"use strict";

var _utilities = require("../../../utilities");
var _ListTemplatesFilter = require("../ListTemplatesFilter.utils");
describe('ListTemplatesFilter.utils', function () {
  describe('convertListTemplatesToFilterOptions', function () {
    var listTemplates = [{
      id: '123',
      title: 'test',
      isActive: true
    }];
    it('return empty', function () {
      expect((0, _ListTemplatesFilter.convertListTemplatesToFilterOptions)(null)).toEqual([]);
    });
    it('should return an array', function () {
      var options = [{
        id: '123',
        isActive: true,
        label: 'test'
      }];
      expect((0, _ListTemplatesFilter.convertListTemplatesToFilterOptions)(listTemplates)).toEqual(options);
    });
    test('should add sublabel as needed', function () {
      listTemplates.push({
        id: '456',
        title: 'Im Mary Poppins yall',
        isActive: false
      });
      var options = [{
        id: '123',
        label: 'test',
        isActive: true
      }, {
        id: '456',
        label: 'Im Mary Poppins yall',
        sublabel: 'Inactive',
        isActive: false
      }];
      expect((0, _ListTemplatesFilter.convertListTemplatesToFilterOptions)(listTemplates)).toEqual(options);
    });
  });
  describe('getUniqueListTemplates', function () {
    test('should default', function () {
      expect((0, _ListTemplatesFilter.getUniqueListTemplates)()).toEqual([]);
      expect((0, _ListTemplatesFilter.getUniqueListTemplates)([])).toEqual([]);
    });
    test('should filter uniques correctly', function () {
      var listTemplates = [{
        id: 1,
        plannedCASourceItemTemplateParentId: null
      }, {
        id: 2,
        plannedCASourceItemTemplateParentId: null
      }, {
        id: 3,
        plannedCASourceItemTemplateParentId: 7
      }, {
        id: 4,
        plannedCASourceItemTemplateParentId: 8
      }, {
        id: 5,
        plannedCASourceItemTemplateParentId: 8
      }];
      expect((0, _ListTemplatesFilter.getUniqueListTemplates)(listTemplates)).toEqual([listTemplates[0], listTemplates[1], listTemplates[2], listTemplates[3]]);
    });
  });
  describe('prependFilterName', function () {
    it('should prepend', function () {
      var callback = jest.fn();
      var isSingleSelection = true;
      (0, _ListTemplatesFilter.prependFilterName)(callback, jest.fn(), null, isSingleSelection)('test');
      expect(callback.mock.calls[0][0]).toEqual(_utilities.FILTER_NAMES.listTemplateIds);
      expect(callback.mock.calls[0][3]).toEqual('test');
      expect(callback.mock.calls[0][4]).toEqual(isSingleSelection);
    });
  });
});